function showAdminCoins(){var m=document.getElementById('adminCoinsModal');m.classList.add('show');var si=document.getElementById('coinsSearchInput');si.value='';document.getElementById('coinsDetail').style.display='none';document.getElementById('coinsSearchList').style.display='block';loadCoinsSearch('');si.oninput=function(){loadCoinsSearch(this.value.trim());};}
function loadCoinsSearch(query){db.ref('u').once('value',function(sn){var d=sn.val();var list=document.getElementById('coinsSearchList');if(!d){list.innerHTML='<p style="color:var(--text2);">Нет</p>';return;}var items=Object.entries(d).map(function(e){return{id:e[0],name:e[1].n||'Игрок',avatar:e[1].a,dollars:e[1].do||0};});if(query)items=items.filter(function(x){return x.name.toLowerCase().includes(query.toLowerCase())||x.id.toLowerCase().includes(query.toLowerCase());});list.innerHTML=items.length===0?'<p style="color:var(--text2);">Ничего</p>':items.map(function(p){return'<div class="lobby-player coins-player" data-pid="'+p.id+'" data-pname="'+p.name+'" data-pavatar="'+p.avatar+'" data-pdollars="'+p.dollars+'"><span class="avatar">'+av(p.avatar)+'</span><span>'+p.name+'</span><span style="color:var(--gold);margin-left:auto;">'+p.dollars+'</span></div>';}).join('');list.querySelectorAll('.coins-player').forEach(function(el){el.addEventListener('click',function(){showCoinsDetail(this.dataset);});});});}
function showCoinsDetail(data){document.getElementById('coinsSearchList').style.display='none';var detail=document.getElementById('coinsDetail');detail.style.display='block';var pid=data.pid;db.ref('coinLog/'+pid).once('value',function(sn){var log=sn.val();var tg=0,tt=0;if(log){tg=log.totalGiven||0;tt=log.totalTaken||0;}detail.innerHTML='<div style="text-align:center;margin-bottom:12px;"><div class="profile-avatar" style="margin:0 auto 10px;width:48px;height:48px;">'+av(data.pavatar)+'</div><h3>'+data.pname+'</h3><p style="color:var(--gold);">Монет: '+data.pdollars+'</p></div><div class="admin-detail"><div class="row"><span class="label">Выдано:</span><span class="value" style="color:var(--green);">+'+tg+'</span></div><div class="row"><span class="label">Отнято:</span><span class="value" style="color:var(--red);">-'+tt+'</span></div></div><div class="coin-input-row"><input type="number" id="coinsAmount" placeholder="Сумма" min="1" value="100"><button class="add" id="coinsAddBtn">Добавить</button></div><div class="coin-input-row"><input type="number" id="coinsTakeAmount" placeholder="Сумма" min="1" value="100"><button class="take" id="coinsTakeBtn">Забрать</button></div><button class="btn" id="coinsBackBtn" style="margin-top:8px;">↩ Назад</button>';document.getElementById('coinsBackBtn').addEventListener('click',function(){detail.style.display='none';document.getElementById('coinsSearchList').style.display='block';document.getElementById('coinsSearchInput').value='';loadCoinsSearch('');});document.getElementById('coinsAddBtn').addEventListener('click',function(){var amt=parseInt(document.getElementById('coinsAmount').value);if(isNaN(amt)||amt<=0){toast('Введите число!');return;}db.ref('u/'+pid+'/do').transaction(function(cur){return(cur||0)+amt;},function(err,committed,sn2){if(err)return;if(committed){db.ref('coinLog/'+pid).update({totalGiven:firebase.database.ServerValue.increment(amt),lastGiven:amt,lastTime:new Date().toLocaleString(),lastAdmin:s.pid});toast('+'+amt);data.pdollars=(sn2.val()||0);detail.querySelector('p').textContent='Монет: '+data.pdollars;}});});document.getElementById('coinsTakeBtn').addEventListener('click',function(){var amt=parseInt(document.getElementById('coinsTakeAmount').value);if(isNaN(amt)||amt<=0){toast('Введите число!');return;}db.ref('u/'+pid+'/do').transaction(function(cur){return Math.max(0,(cur||0)-amt);},function(err,committed,sn2){if(err)return;if(committed){db.ref('coinLog/'+pid).update({totalTaken:firebase.database.ServerValue.increment(amt),lastTaken:amt,lastTakenTime:new Date().toLocaleString(),lastAdmin:s.pid});toast('-'+amt);data.pdollars=(sn2.val()||0);detail.querySelector('p').textContent='Монет: '+data.pdollars;}});});});}
function showAdminBan(){var m=document.getElementById('adminBanModal');m.classList.add('show');var si=document.getElementById('banSearchInput');si.value='';document.getElementById('banDetail').style.display='none';document.getElementById('banSearchList').style.display='block';loadBanSearch('');si.oninput=function(){loadBanSearch(this.value.trim());};}
function loadBanSearch(query){db.ref('u').once('value',function(sn){var d=sn.val();var list=document.getElementById('banSearchList');if(!d){list.innerHTML='<p style="color:var(--text2);">Нет</p>';return;}var items=Object.entries(d).map(function(e){return{id:e[0],name:e[1].n||'Игрок',avatar:e[1].a,banned:e[1].banned||false,muted:e[1].muted||false};});if(query)items=items.filter(function(x){return x.name.toLowerCase().includes(query.toLowerCase())||x.id.toLowerCase().includes(query.toLowerCase());});list.innerHTML=items.length===0?'<p style="color:var(--text2);">Ничего</p>':items.map(function(p){return'<div class="lobby-player ban-player" data-pid="'+p.id+'" data-pname="'+p.name+'" data-pavatar="'+p.avatar+'" data-banned="'+p.banned+'" data-muted="'+p.muted+'"><span class="avatar">'+av(p.avatar)+'</span><span>'+p.name+'</span><span style="margin-left:auto;font-size:9px;color:'+(p.banned?'var(--red)':p.muted?'var(--orange)':'var(--green)')+';">'+(p.banned?'BAN':p.muted?'MUTE':'OK')+'</span></div>';}).join('');list.querySelectorAll('.ban-player').forEach(function(el){el.addEventListener('click',function(){showBanDetail(this.dataset);});});});}
function showBanDetail(data){document.getElementById('banSearchList').style.display='none';var detail=document.getElementById('banDetail');detail.style.display='block';var pid=data.pid;var banned=data.banned==='true';var muted=data.muted==='true';detail.innerHTML='<div style="text-align:center;margin-bottom:12px;"><div class="profile-avatar" style="margin:0 auto 10px;width:48px;height:48px;">'+av(data.pavatar)+'</div><h3>'+data.pname+'</h3></div><p style="text-align:center;color:'+(banned?'var(--red)':muted?'var(--orange)':'var(--green)')+';">'+(banned?'ЗАБАНЕН':muted?'ЗАМУЧЕН':'Активен')+'</p><div class="coin-input-row"><button class="'+(banned?'add':'take')+'" id="banToggleBtn">'+(banned?'Разбанить':'Забанить')+'</button></div><div style="display:flex;gap:8px;margin-top:8px;"><input type="text" id="banReasonInput" placeholder="Причина" style="flex:1;padding:12px;background:#000;border:2px solid var(--gold);color:#fff;border-radius:10px;font-size:14px;"><input type="number" id="banMinutesInput" placeholder="Минут" min="1" value="60" style="width:80px;padding:12px;background:#000;border:2px solid var(--gold);color:#fff;border-radius:10px;font-size:14px;text-align:center;"></div><div class="coin-input-row" style="margin-top:8px;"><input type="number" id="muteMinutes" placeholder="Минут" min="1" value="60"><button class="'+(muted?'add':'take')+'" id="muteToggleBtn">'+(muted?'Размутить':'Замутить')+'</button></div><div class="coin-input-row"><input type="text" id="newNickInput" placeholder="Новый ник"><button class="add" id="changeNickBtn">Сменить</button></div><button class="btn" id="banBackBtn" style="margin-top:8px;">↩ Назад</button>';document.getElementById('banBackBtn').addEventListener('click',function(){detail.style.display='none';document.getElementById('banSearchList').style.display='block';document.getElementById('banSearchInput').value='';loadBanSearch('');});document.getElementById('banToggleBtn').addEventListener('click',function(){if(banned){db.ref('u/'+pid+'/banned').set(false);db.ref('u/'+pid+'/banReason').remove();db.ref('u/'+pid+'/banUntil').remove();toast('Разбанен');}else{var reason=document.getElementById('banReasonInput').value.trim()||'Нарушение';var mins=parseInt(document.getElementById('banMinutesInput').value)||60;db.ref('u/'+pid+'/banned').set(true);db.ref('u/'+pid+'/banReason').set(reason);db.ref('u/'+pid+'/banUntil').set(Date.now()+mins*60000);toast('Забанен на '+mins+' мин');}data.banned=(!banned).toString();showBanDetail(data);});document.getElementById('muteToggleBtn').addEventListener('click',function(){var mins=parseInt(document.getElementById('muteMinutes').value)||60;if(muted){db.ref('u/'+pid+'/muted').set(false);db.ref('u/'+pid+'/muteUntil').remove();toast('Размучен');}else{db.ref('u/'+pid+'/muted').set(true);db.ref('u/'+pid+'/muteUntil').set(Date.now()+mins*60000);toast('Замучен на '+mins+' мин');}data.muted=(!muted).toString();showBanDetail(data);});document.getElementById('changeNickBtn').addEventListener('click',function(){var nn=document.getElementById('newNickInput').value.trim();if(!nn){toast('Введите ник!');return;}db.ref('u/'+pid+'/n').set(nn);toast('Ник изменён');});}
function showAdminStats(){var m=document.getElementById('adminStatsModal');m.classList.add('show');var c=document.getElementById('statsContent');c.innerHTML='<p>Загрузка...</p>';db.ref('u').once('value',function(sn){var d=sn.val();if(!d)return;var tc=0;var pl=Object.entries(d).map(function(e){tc+=e[1].do||0;return{name:e[1].n||'Игрок',coins:e[1].do||0};}).sort(function(a,b){return b.coins-a.coins;});c.innerHTML='<div class="admin-detail"><div class="row"><span class="label">Всего монет:</span><span class="value" style="color:var(--gold);">'+tc+'</span></div><div class="row"><span class="label">Игроков:</span><span class="value">'+pl.length+'</span></div></div><div class="section-title">Топ-10</div>'+pl.slice(0,10).map(function(p,i){return'<div class="lobby-player"><span>'+(i+1)+'.</span><span>'+p.name+'</span><span style="margin-left:auto;color:var(--gold);">'+p.coins+'</span></div>';}).join('');});}
function showAdminBroadcast(){var m=document.getElementById('adminBroadcastModal');m.classList.add('show');document.getElementById('broadcastMsg').value='';document.getElementById('broadcastCoins').value='0';document.getElementById('broadcastDuration').value='10';document.getElementById('broadcastSendBtn').onclick=function(){var msg=document.getElementById('broadcastMsg').value.trim();var coins=parseInt(document.getElementById('broadcastCoins').value)||0;var dur=parseInt(document.getElementById('broadcastDuration').value)||10;if(!msg&&!coins){toast('Введите текст или монеты!');return;}var now=Date.now();var annRef=db.ref('announcements').push();annRef.set({text:msg,coins:coins,createdAt:now,expireAt:now+dur*1000,time:firebase.database.ServerValue.TIMESTAMP});if(coins>0){db.ref('on').once('value',function(sn){var d=sn.val();if(!d)return;Object.keys(d).forEach(function(id){db.ref('u/'+id+'/do').transaction(function(cur){return(cur||0)+coins;});});});}toast('Отправлено!');m.classList.remove('show');};}
function showAdminReports(){var m=document.getElementById('adminReportsModal');m.classList.add('show');db.ref('support').once('value',function(sn){var d=sn.val();var list=document.getElementById('reportsList');if(!d){list.innerHTML='<p style="color:var(--text2);">Нет</p>';return;}list.innerHTML=Object.entries(d).map(function(e){var r=e[1];return'<div style="background:var(--surface);border-radius:8px;padding:10px;margin:4px 0;font-size:11px;"><div style="color:var(--gold);">'+(r.fromName||'Игрок')+'</div><div style="color:var(--text);margin:4px 0;">'+r.text+'</div><button class="btn-sm close-report" data-id="'+e[0]+'" style="border-color:var(--green);color:var(--green);margin-top:6px;">Закрыть</button></div>';}).join('');list.querySelectorAll('.close-report').forEach(function(b){b.addEventListener('click',function(){db.ref('support/'+b.dataset.id).remove();showAdminReports();});});});}
function showAdminSettings(){var m=document.getElementById('adminSettingsModal');m.classList.add('show');db.ref('settings/startCoins').once('value',function(sn){document.getElementById('startCoinsInput').value=sn.val()!==undefined?sn.val():100;});document.getElementById('startCoinsSaveBtn').onclick=function(){var val=parseInt(document.getElementById('startCoinsInput').value);if(isNaN(val)||val<0){toast('0 или больше!');return;}db.ref('settings/startCoins').set(val);toast('Монеты: '+val);};document.getElementById('avatarUrlSaveBtn').onclick=function(){var url=document.getElementById('avatarUrlInput').value.trim();var target=document.getElementById('avatarPlayerSearch').value.trim();if(!url){toast('Введите URL!');return;}var pid=target?null:s.pid;if(target){db.ref('u').orderByChild('n').equalTo(target).once('value',function(sn){var u=sn.val();if(u){pid=Object.keys(u)[0];}if(!pid){toast('Не найден, себе');pid=s.pid;}addCustomAvatar(pid,url);});}else{addCustomAvatar(s.pid,url);}};document.getElementById('musicUrlSaveBtn').onclick=function(){var url=document.getElementById('musicUrlInput').value.trim();var target=document.getElementById('musicPlayerSearch').value.trim();if(!url){toast('Введите URL!');return;}var pid=target?null:s.pid;if(target){db.ref('u').orderByChild('n').equalTo(target).once('value',function(sn){var u=sn.val();if(u){pid=Object.keys(u)[0];}if(!pid){toast('Не найден, себе');pid=s.pid;}addCustomMusic(pid,url);});}else{addCustomMusic(s.pid,url);}};loadCustomAvatars();loadCustomMusic();}
