function addCustomMusic(pid,url){db.ref('settings/customMusic/'+pid).push(url);toast('Музыка добавлена!');loadCustomMusic();}
function loadCustomAvatars(){db.ref('settings/customAvatars').once('value',function(sn){var d=sn.val();var list=document.getElementById('customAvatarsList');if(!d){list.innerHTML='';return;}var h='<div class="section-title">Аватарки</div>';Object.entries(d).forEach(function(e){var pid=e[0];var urls=e[1];if(!urls)return;Object.entries(urls).forEach(function(e2){h+='<div class="lobby-player"><span style="font-size:9px;">'+pid+'</span><span class="btn-sm" data-pid="'+pid+'" data-key="'+e2[0]+'" style="margin-left:auto;color:var(--red);">✕</span></div>';});});list.innerHTML=h;list.querySelectorAll('.btn-sm').forEach(function(b){b.addEventListener('click',function(){db.ref('settings/customAvatars/'+b.dataset.pid+'/'+b.dataset.key).remove();db.ref('u/'+b.dataset.pid+'/a').set('icons/avatar1.png');toast('Удалён');loadCustomAvatars();});});});}
function loadCustomMusic(){db.ref('settings/customMusic').once('value',function(sn){var d=sn.val();var list=document.getElementById('customMusicList');if(!d){list.innerHTML='';return;}var h='<div class="section-title">Музыка</div>';Object.entries(d).forEach(function(e){var pid=e[0];var urls=e[1];if(!urls)return;Object.entries(urls).forEach(function(e2){h+='<div class="lobby-player"><span style="font-size:9px;">'+pid+'</span><span class="btn-sm" data-pid="'+pid+'" data-key="'+e2[0]+'" style="margin-left:auto;color:var(--red);">✕</span></div>';});});list.innerHTML=h;list.querySelectorAll('.btn-sm').forEach(function(b){b.addEventListener('click',function(){db.ref('settings/customMusic/'+b.dataset.pid+'/'+b.dataset.key).remove();toast('Удалена');loadCustomMusic();});});});}
function showSupportModal(){var m=document.getElementById('supportModal');m.classList.add('show');var now=Date.now();var cd=300000;var remaining=cd-(now-s.lastSupportTime);if(remaining>0){var mins=Math.ceil(remaining/60000);document.getElementById('supportCd').textContent='Повторно через '+mins+' мин.';document.getElementById('supportSendBtn').disabled=true;}else{document.getElementById('supportCd').textContent='';document.getElementById('supportSendBtn').disabled=false;}document.getElementById('supportMsg').value='';document.getElementById('supportSendBtn').onclick=function(){var msg=document.getElementById('supportMsg').value.trim();if(!msg){toast('Введите текст!');return;}var now2=Date.now();if(now2-s.lastSupportTime<cd){toast('Подождите!');return;}s.lastSupportTime=now2;db.ref('support').push({from:s.pid,fromName:s.pn,text:msg,time:firebase.database.ServerValue.TIMESTAMP,saved:false});sS();toast('Отправлено!');m.classList.remove('show');};}
