document.getElementById('customInputOk').addEventListener('click',function(){var val=parseInt(document.getElementById('customInputValue').value);if(isNaN(val)||val<s.customChipMin||val>s.customChipMax){alert('От '+s.customChipMin+' до '+s.customChipMax+'!');return;}document.getElementById('customInputOverlay').classList.remove('show');if(s.customChipCallback)s.customChipCallback(val);});
