function showInviteModal(friendId,friendName,friendAvatar){s.rc=Math.random().toString(36).substring(2,8).toUpperCase();db.ref('rooms/'+s.rc).set({hid:s.pid,rn:'Комната',mp:4,sc:10000,rt:30,tr:5,pl:{},st:'waiting',access:'open',rm:'hard',bet:0});document.getElementById('inviteFriendList').innerHTML='<div class="lobby-player" style="cursor:pointer;" id="sendInvite"><span class="avatar">'+av(friendAvatar||'?')+'</span>'+friendName+' — Отправить</div>';document.getElementById('sendInvite').addEventListener('click',function(){sendGameInvite(friendId);});document.getElementById('inviteModal').classList.add('show');}
document.getElementById('inviteCloseBtn').addEventListener('click',function(){document.getElementById('inviteModal').classList.remove('show');});
function searchFriendByName(query){if(!query||query.length<2)return;db.ref('u').orderByChild('n').startAt(query).endAt(query+'\uf8ff').limitToFirst(10).once('value',function(sn){var u=sn.val();var res=document.getElementById('friendSearchResults');if(!u){res.innerHTML='<p style="color:var(--text2);">Ничего</p>';return;}var filtered=Object.entries(u).filter(function(e){return e[0]!==s.pid;});res.innerHTML=filtered.length===0?'<p style="color:var(--text2);">Ничего</p>':filtered.map(function(e){var id=e[0],ud=e[1],isFriend=s.fr.includes(id);return'<div class="lobby-player"><span class="avatar">'+av(ud.a)+'</span><span>'+(ud.n||'Игрок')+'</span>'+(!isFriend?'<button class="btn-sm add-fr-btn" data-id="'+id+'" style="border-color:var(--gold);color:var(--gold);margin-left:auto;">Добавить</button>':'<span style="color:var(--green);margin-left:4px;">✓</span>')+(s.inviteFromRoom?'<button class="btn-sm invite-fr-btn-room" data-id="'+id+'" data-name="'+(ud.n||'Игрок')+'" data-avatar="'+(ud.a||'')+'" style="border-color:var(--blue);color:var(--blue);margin-left:4px;">В комн.</button>':'<button class="btn-sm invite-fr-btn" data-id="'+id+'" data-name="'+(ud.n||'Игрок')+'" data-avatar="'+(ud.a||'')+'" style="border-color:var(--blue);color:var(--blue);margin-left:4px;">Пригл.</button>')+'</div>';}).join('');res.querySelectorAll('.add-fr-btn').forEach(function(b){b.addEventListener('click',function(){sendFriendRequest(b.dataset.id);b.textContent='✓';b.disabled=true;});});res.querySelectorAll('.invite-fr-btn').forEach(function(b){b.addEventListener('click',function(){showInviteModal(b.dataset.id,b.dataset.name,b.dataset.avatar);});});res.querySelectorAll('.invite-fr-btn-room').forEach(function(b){b.addEventListener('click',function(){inviteToGameFromRoom(b.dataset.id);});});},function(e){cl('Ошибка: '+e.message,'error');});}
document.getElementById('friendSearchInput').addEventListener('input',function(){searchFriendByName(this.value.trim());});
function inviteToGameFromRoom(friendId){if(!s.rc)return;db.ref('gi/'+friendId+'/'+s.rc).set({from:s.pid,fromName:s.pn,fromAvatar:s.pa,roomCode:s.rc,roomName:s.rn,bet:s.bet,mp:s.mp,sc:s.sc,rt:s.rt,tr:s.tr,rm:s.rm,status:'pending',ts:firebase.database.ServerValue.TIMESTAMP});toast('Приглашение в комнату!');}
