function showFriendsModal(){var m=document.getElementById('friendsModal');m.classList.add('show');if(s.frc.length===0){document.getElementById('frcList').innerHTML='<p style="color:var(--text2);">Нет</p>';}else{Promise.all(s.frc.map(function(id){return db.ref('u/'+id).once('value');})).then(function(snaps){var h='';snaps.forEach(function(sn,i){var d=sn.val();if(d)h+='<div class="lobby-player"><span class="avatar">'+av(d.a)+'</span>'+(d.n||'Игрок')+' <button class="btn-sm accept-fr" data-id="'+s.frc[i]+'" style="border-color:var(--green);color:var(--green);">V</button> <button class="btn-sm decline-fr" data-id="'+s.frc[i]+'" style="border-color:var(--red);color:var(--red);">X</button></div>';});document.getElementById('frcList').innerHTML=h||'<p>Нет</p>';document.querySelectorAll('.accept-fr').forEach(function(b){b.onclick=function(){acceptFriendRequest(b.dataset.id);showFriendsModal();};});document.querySelectorAll('.decline-fr').forEach(function(b){b.onclick=function(){declineFriendRequest(b.dataset.id);showFriendsModal();};});}).catch(function(e){cl('Ошибка: '+e.message,'error');});}if(s.gi.length===0){document.getElementById('gameInvitesList').innerHTML='<p style="color:var(--text2);">Нет</p>';}else{Promise.all(s.gi.map(function(e){return db.ref('u/'+e[1].from).once('value');})).then(function(snaps){var h='';snaps.forEach(function(sn,i){var d=sn.val();var inv=s.gi[i][1];if(d&&inv){var isTransfer=inv.status==='host_transfer';h+='<div class="lobby-player"><span class="avatar">'+av(inv.fromAvatar||d.a)+'</span>'+(d.n||'Игрок')+' → '+(inv.roomName||'Комната')+(inv.bet>0?' ['+inv.bet+']':'')+' '+(isTransfer?'<span style="color:var(--gold);font-size:9px;">Хост</span>':'')+' <button class="btn-sm accept-gi" data-inv-id="'+s.gi[i][0]+'" data-inv="'+encodeURIComponent(JSON.stringify(inv))+'" style="border-color:var(--green);color:var(--green);">'+(isTransfer?'Настр.':'V')+'</button> <button class="btn-sm decline-gi" data-inv-id="'+s.gi[i][0]+'" style="border-color:var(--red);color:var(--red);">X</button></div>';}});document.getElementById('gameInvitesList').innerHTML=h||'<p>Нет</p>';document.querySelectorAll('.accept-gi').forEach(function(b){b.onclick=function(){var inv=JSON.parse(decodeURIComponent(b.dataset.inv));acceptGameInvite(b.dataset.invId,inv);};});document.querySelectorAll('.decline-gi').forEach(function(b){b.onclick=function(){declineGameInvite(b.dataset.invId);showFriendsModal();};});}).catch(function(e){cl('Ошибка: '+e.message,'error');});}if(s.fr.length===0){document.getElementById('friendsList').innerHTML='<p style="color:var(--text2);">Нет</p>';}else{Promise.all(s.fr.map(function(id){return db.ref('u/'+id).once('value');})).then(function(snaps){var h='';snaps.forEach(function(sn){var d=sn.val();if(d)h+='<div class="lobby-player"><span class="avatar">'+av(d.a)+'</span>'+(d.n||'Игрок')+' <button class="btn-sm invite-game" data-id="'+sn.key+'" style="border-color:var(--blue);color:var(--blue);">'+(s.inviteFromRoom?'В комн.':'Пригл.')+'</button></div>';});document.getElementById('friendsList').innerHTML=h||'<p>Нет</p>';document.querySelectorAll('.invite-game').forEach(function(b){b.onclick=function(){if(s.inviteFromRoom){inviteToGameFromRoom(b.dataset.id);}else{inviteToGame(b.dataset.id);}};});}).catch(function(e){cl('Ошибка: '+e.message,'error');});}}
