var mt=['music/track1.mp3','music/track2.mp3','music/track3.mp3'];var ct=0,mo=false;var bm=new Audio();
function pnt(){if(!mo||!mt[ct])return;bm.src=mt[ct];bm.play().catch(function(){});bm.onended=function(){ct=(ct+1)%mt.length;pnt();};}
function genGameCases(){s.gameCases=[];s.gameRound=0;var ui=[];for(var i=0;i<s.tr;i++){var v=s.acl.filter(function(c){return c&&c.symbol&&!ui.includes(c.id);});var k=v.length>0?v[Math.floor(Math.random()*v.length)]:s.acl[0];if(!k)continue;ui.push(k.id);s.gameCases.push({id:k.id,symbol:k.symbol,round:i+1,name:k.name||'',desc:k.desc||'',trend:k.trend||'volatile'});}}
function grc(){if(s.im&&s.gameCases.length>0){if(s.gameRound>=s.gameCases.length)s.gameRound=0;var k=s.gameCases[s.gameRound];s.gameRound++;if(k&&k.symbol&&!s.uc.includes(k.id)){return k;}}var p=s.fa?s.acl.filter(function(c){return c&&c.symbol&&c.price&&c.price>=1&&c.price<=15;}):s.acl;var v=p.filter(function(c){return c&&c.symbol&&c.price&&!s.uc.includes(c.id);});if(!v.length){s.uc=[];return p[Math.floor(Math.random()*p.length)];}return v[Math.floor(Math.random()*v.length)];}
function ump(){var cs=s.fa?s.acl.filter(function(c){return c&&c.price&&c.price>=1&&c.price<=15;}):s.acl;for(var i=0;i<cs.length;i++){var c=cs[i];if(!c||!c.symbol||!c.price)continue;if(!s.mk[c.symbol]){s.mk[c.symbol]=Number(c.price)||10;s.fv[c.symbol]=Number(c.price)||10;}var cu=s.mk[c.symbol],fa=s.fv[c.symbol],vm=s.fa?2.5:1;var tb=c.trend=='up'?0.5:c.trend=='down'?-0.4:c.trend=='volatile'?(Math.random()-0.5)*1.5:0;var ft=Math.random()<0.667,bias=ft?tb:-tb;var ch=(fa-cu)/fa*30*vm+(Math.random()-0.5+bias*0.4)*12*vm;if(Math.random()<0.06*vm)ch=(Math.random()>0.5?1:-1)*(15+Math.random()*20);ch=Math.max(-50,Math.min(50,ch));s.mk[c.symbol]=Math.max(0.05,cu*(1+ch/100));s.fv[c.symbol]=fa*(1+(Math.random()-0.49)*4/100);}if((s.isGhost||s.cheats.predictOutcome)&&isAdmin()&&s.cc){updateGhostPredict();}}
function updateGhostPredict(){if(!s.cc)return;var sym=s.cc.symbol,pr=s.mk[sym]||s.cc.price,fair=s.fv[sym]||pr;var changePercent=(fair-pr)/pr*100;var direction=changePercent>0?'↑':'↓';var color=changePercent>0?'var(--green)':'var(--red)';document.getElementById('ghostPredictBox').innerHTML='🔮 <b>ПРОГНОЗ:</b> <span style="color:'+color+';">'+direction+' '+Math.abs(changePercent).toFixed(1)+'%</span><br>💰 '+fm2(pr)+' | ⚖️ '+fm2(fair);}
