function showConfirm(msg,callback){document.getElementById('confirmMsg').textContent=msg;document.getElementById('confirmModal').classList.add('show');document.getElementById('confirmYes').onclick=function(){document.getElementById('confirmModal').classList.remove('show');if(callback)callback(true);};document.getElementById('confirmNo').onclick=function(){document.getElementById('confirmModal').classList.remove('show');if(callback)callback(false);};}
window.setBuyQty=function(v){var inp=document.getElementById('buyQty');if(v==='max'){inp.value=Math.floor(s.yc/(s.cc?s.mk[s.cc.symbol]||s.cc.price:1));if(inp.value<1)inp.value='1';}else{inp.value=v;}ubb();};
function upt(){var b=document.getElementById('portfolioBody'),as=Object.entries(s.yp);b.innerHTML=as.length===0?'<tr><td colspan="8">Нет активов<\/td><\/tr>':as.map(function(e){var sym=e[0],d=e[1];var pr=s.mk[sym]||d.avgPrice,val=pr*d.qty,pc=d.avgPrice?((pr-d.avgPrice)/d.avgPrice*100):0;var cls=+pc>=0?'up':'down',arr=+pc>=0?'+':'',p=Math.abs(pc).toFixed(1);var rowCls=+pc>=5?'gain':(+pc<=-5?'loss':'');var caseItem=s.acl.find(function(c){return c&&c.symbol===sym;});var comment='';if(caseItem){comment=+pc>=0?(caseItem.reason_up||''):(caseItem.reason_down||'');}var prediction='';var predColor='';if(isAdmin()&&s.cheats.predictOutcome&&s.fv[sym]){var fair=s.fv[sym];var changePercent=(fair-pr)/pr*100;if(changePercent>0){prediction='↑+'+changePercent.toFixed(1)+'%';predColor='var(--green)';}else{prediction='↓'+Math.abs(changePercent).toFixed(1)+'%';predColor='var(--red)';}}return'<tr class="'+rowCls+'"><td class="sym">'+sym+'<\/td><td>'+d.qty+'<\/td><td>'+fm2(pr)+'<\/td><td>'+fm2(val)+'<\/td><td class="'+cls+'">'+arr+p+'%<\/td><td style="color:'+predColor+';font-weight:bold;">'+prediction+'<\/td><td class="pf-comment" title="'+(comment||'')+'">'+(comment||'—')+'<\/td><td><input class="qty-input" id="sq_'+sym+'" value="'+d.qty+'"><button class="btn-sm sell" id="sl_'+sym+'">Продать<\/button><\/td><\/tr>';}).join('');as.forEach(function(e){var sym=e[0];var btn=document.getElementById('sl_'+sym);if(btn)btn.onclick=function(){var d=s.yp[sym];if(!d)return;var inp=document.getElementById('sq_'+sym);var q=Math.max(1,Math.min(d.qty,parseInt((inp||{}).value)||d.qty));s.yc+=(s.mk[sym]||d.avgPrice)*q;d.qty-=q;if(d.qty<=0)delete s.yp[sym];playSellSound();upt();upr();sy();};});}
function upr(){if(s.isGhost){var activeLP=s.lp.filter(function(p){return!s.leftPlayers.includes(p.id);});var ps=activeLP.map(function(p){return{n:p.n,a:p.a,c:p.c||s.sc,you:false,id:p.id,left:s.leftPlayers.includes(p.id)};});document.getElementById('playersRow').innerHTML=ps.map(function(p){return'<div class="player-card '+(p.left?'left ':'')+'"><div class="avatar">'+av(p.a)+'</div><div class="name">'+p.n+(p.left?' (вышел)':'')+'</div><div class="cash">'+fm2(p.c)+'</div></div>';}).join('');return;}var activeLP=s.lp.filter(function(p){return!s.leftPlayers.includes(p.id);});var ps=s.im&&activeLP.length>0?activeLP.map(function(p){return{n:p.n,a:p.a,c:p.c||s.sc,you:p.id===s.pid,id:p.id,left:s.leftPlayers.includes(p.id)};}):[{n:s.pn,a:s.pa,c:s.yc,you:true},{n:s.on,a:s.oa,c:s.oc,you:false}];document.getElementById('playersRow').innerHTML=ps.map(function(p){return'<div class="player-card '+(p.you?'you ':'')+(p.left?'left ':'')+'" data-pid="'+(p.id||'')+'" data-pname="'+p.n+'" data-pavatar="'+p.a+'"><div class="avatar">'+av(p.a)+'</div><div class="name">'+p.n+(p.left?' (вышел)':'')+'</div><div class="cash">'+fm2(p.c)+'</div></div>';}).join('');document.querySelectorAll('.player-card:not(.you):not(.left)').forEach(function(card){card.addEventListener('click',function(){showPlayerProfile(card.dataset);});});}
function showPlayerProfile(data){if(data.pid===s.pid)return;var c=document.getElementById('ppContent');var isFriend=s.fr.includes(data.pid);c.innerHTML='<h3>'+(data.pname||'Игрок')+'</h3><div class="profile-avatar" style="margin:0 auto 10px;width:64px;height:64px;">'+av(data.pavatar)+'</div><p>'+(data.pname||'Игрок')+'</p>'+(!isFriend&&data.pid?'<button class="btn gold" id="addFriendBtn">Добавить в друзья</button>':'')+'<button class="btn gold" id="offerTradeBtn" style="margin-top:6px;">Купить акции</button>';document.getElementById('playerProfileModal').classList.add('show');var afb=document.getElementById('addFriendBtn');if(afb)afb.addEventListener('click',function(){sendFriendRequest(data.pid);document.getElementById('playerProfileModal').classList.remove('show');});var otb=document.getElementById('offerTradeBtn');if(otb)otb.addEventListener('click',function(){showTradeOffer(data);});}
function showTradeOffer(data){var c=document.getElementById('tradeContent');c.innerHTML='<h3>Купить акции у '+data.pname+'</h3><div class="section-title">Ваши деньги: '+fm2(s.yc)+'</div><div id="tradeSymbols"></div>';document.getElementById('tradeModal').classList.add('show');var oppPortfolio=s.im&&s.rc?(s.lp.find(function(p){return p.id===data.pid;})||{}).p||{}:s.op||{};var syms=Object.keys(oppPortfolio).filter(function(sym){return oppPortfolio[sym]&&oppPortfolio[sym].qty>0;});if(syms.length===0){c.innerHTML+='<p style="color:var(--text2);">Нет акций</p>';return;}document.getElementById('tradeSymbols').innerHTML=syms.map(function(sym){var pr2=s.mk[sym]||10;return'<div style="background:var(--surface);padding:10px;border-radius:8px;margin:4px 0;cursor:pointer;" class="trade-sym" data-sym="'+sym+'" data-price="'+pr2+'" data-target="'+data.pid+'"><b>'+sym+'</b> | '+fm2(pr2)+' | Доступно: '+oppPortfolio[sym].qty+'</div>';}).join('');document.querySelectorAll('.trade-sym').forEach(function(el){el.addEventListener('click',function(){var sym2=el.dataset.sym,pr3=parseFloat(el.dataset.price),target2=el.dataset.target;if(s.yc>=pr3){var tradeKey=target2+'_'+sym2;if(s.tradeShown[tradeKey]){toast('Предложение уже отправлено!');return;}s.tradeShown[tradeKey]=true;db.ref('rooms/'+s.rc+'/trades/'+tradeKey).set({from:s.pid,to:target2,sym:sym2,price:pr3,qty:1,fromName:s.pn,status:'pending',ts:firebase.database.ServerValue.TIMESTAMP},function(e){if(e){cl('Ошибка: '+e.message,'error');s.tradeShown[tradeKey]=false;}else{toast('Предложение: '+sym2);document.getElementById('tradeModal').classList.remove('show');}});}else{toast('Недостаточно денег');}});});}
function showTradeRequest(trade){var key=trade.from+'_'+trade.sym;if(s.tradeShown[key])return;s.tradeShown[key]=true;var el2=document.getElementById('tradeNotice');el2.innerHTML='<b>'+trade.fromName+'</b> хочет купить <b>'+trade.sym+'</b> за <b>'+fm2(trade.price)+'</b><br><button class="btn-sm" id="acceptTrade" style="border-color:var(--green);color:var(--green);">Принять</button> <button class="btn-sm" id="declineTrade" style="border-color:var(--red);color:var(--red);">Отклонить</button>';el2.classList.add('show');document.getElementById('acceptTrade').addEventListener('click',function(){if(s.op[trade.sym]&&s.op[trade.sym].qty>0){s.oc+=trade.price;s.op[trade.sym].qty--;if(s.op[trade.sym].qty<=0)delete s.op[trade.sym];db.ref('rooms/'+s.rc+'/pl/'+trade.from).once('value',function(sn){var fd=sn.val();if(fd){var fc=fd.c||0;fc-=trade.price;if(!fd.p)fd.p={};if(!fd.p[trade.sym])fd.p[trade.sym]={qty:0,avgPrice:0};fd.p[trade.sym].qty++;fd.p[trade.sym].avgPrice=trade.price;db.ref('rooms/'+s.rc+'/pl/'+trade.from).update({c:fc,p:fd.p});}});delete s.tradeShown[key];db.ref('rooms/'+s.rc+'/trades/'+key).update({status:'done'});toast('Сделка!');}el2.classList.remove('show');});document.getElementById('declineTrade').addEventListener('click',function(){delete s.tradeShown[key];db.ref('rooms/'+s.rc+'/trades/'+key).update({status:'declined'});el2.classList.remove('show');});setTimeout(function(){el2.classList.remove('show');delete s.tradeShown[key];},15000);}
function shc(k){if(!k||!k.symbol)return;s.cc=k;if(!s.mk[k.symbol]){s.mk[k.symbol]=Number(k.price)||10;s.fv[k.symbol]=Number(k.price)||10;}document.getElementById('caseTitle').textContent=k.symbol+' - '+(k.name||'');document.getElementById('caseDesc').textContent=k.desc||'';var price=s.mk[k.symbol];var priceHtml=fm2(price);if(isAdmin()&&s.cheats.predictOutcome&&s.fv[k.symbol]){var fair=s.fv[k.symbol];var changePercent=(fair-price)/price*100;if(changePercent>0){priceHtml+=' <span style="color:var(--green);">↑+'+changePercent.toFixed(1)+'%</span>';}else{priceHtml+=' <span style="color:var(--red);">↓'+Math.abs(changePercent).toFixed(1)+'%</span>';}}document.getElementById('casePrice').innerHTML=priceHtml;document.getElementById('roundBadge').textContent=s.cr+'/'+s.tr;upt();upr();ubb();if((s.isGhost||s.cheats.predictOutcome)&&isAdmin())updateGhostPredict();}
function ubb(){var k=s.cc;if(!k)return;var pr=s.mk[k.symbol]||k.price;var inp=document.getElementById('buyQty');var q=Math.max(1,parseInt((inp||{}).value)||1);if(isNaN(q))q=1;document.getElementById('buyBtn').disabled=s.yc<pr*q;}
function pBuy(){if(!s.ga||s.fi||!s.cc||s.isGhost)return;var k=s.cc,pr=s.mk[k.symbol]||k.price,inp=document.getElementById('buyQty'),q=Math.max(1,parseInt((inp||{}).value)||1);if(isNaN(q))q=1;if(s.yc<pr*q)return;s.yc-=pr*q;if(!s.yp[k.symbol])s.yp[k.symbol]={qty:0,avgPrice:0};var o=s.yp[k.symbol];o.avgPrice=(o.qty*o.avgPrice+pr*q)/(o.qty+q);o.qty+=q;playBuySound();upt();upr();ubb();sy();}
function slA(){if(Object.keys(s.yp).length===0)return;showConfirm('Продать ВСЕ активы?',function(yes){if(yes){for(var sym in s.yp){s.yc+=(s.mk[sym]||s.yp[sym].avgPrice)*s.yp[sym].qty;}s.yp={};playSellSound();upt();upr();sy();}});}
function tw(){if(!s.im||s.isGhost){nr();return;}if(s.wp)return;s.wp=true;document.getElementById('waitBtn').classList.add('held');if(s.rc)db.ref('rooms/'+s.rc+'/rd/'+s.pid).set(true);}
function sy(){if(!s.rc||!s.im)return;db.ref('rooms/'+s.rc+'/pl/'+s.pid).update({n:s.pn,a:s.pa,c:s.yc,p:s.yp});}
function botA(){if(!s.cc||s.im)return;var sym=s.cc.symbol,pr=s.mk[sym]||s.cc.price,ip=s.op[sym],fair=s.fv[sym]||pr;if(Math.random()<0.8&&s.oc>=pr*2){var maxQ=Math.floor(s.oc/pr);var q=Math.floor(Math.random()*8)+3;if(q>maxQ)q=maxQ;if(q>0&&s.oc>=pr*q){s.oc-=pr*q;if(!s.op[sym])s.op[sym]={qty:0,avgPrice:0};var o=s.op[sym];o.avgPrice=(o.qty*o.avgPrice+pr*q)/(o.qty+q);o.qty+=q;}}else if(ip&&ip.qty>0&&(pr>ip.avgPrice*1.15||pr>fair*1.08)){var q=Math.min(ip.qty,Math.ceil(ip.qty*0.8));if(q>0){s.oc+=pr*q;ip.qty-=q;if(ip.qty<=0)delete s.op[sym];}}upr();}
