function calcRoomParams(r){if(!r.votes||Object.keys(r.votes).length===0)return;var totals={sc:r.sc||10000,rt:r.rt||30,tr:r.tr||5};var cnt=1;for(var k in r.votes){var v=r.votes[k];totals.sc+=v.sc||r.sc;totals.rt+=v.rt||r.rt;totals.tr+=v.tr||r.tr;cnt++;}db.ref('rooms/'+s.rc).update({sc:Math.ceil(totals.sc/cnt),rt:Math.ceil(totals.rt/cnt),tr:Math.ceil(totals.tr/cnt)});}
