function resetChipsToValue(rowId,key,value){var row=document.getElementById(rowId);if(!row)return;row.querySelectorAll('.chip').forEach(function(c){c.classList.remove('selected');});row.querySelectorAll('.chip.custom-selected').forEach(function(c){c.remove();});var found=false;row.querySelectorAll('.chip:not(.custom)').forEach(function(c){if(c.dataset[key]==value){c.classList.add('selected');found=true;}});if(!found){var newChip=document.createElement('div');newChip.className='chip selected custom-selected';newChip.dataset[key]=value;newChip.textContent=value;newChip.addEventListener('click',function(){row.querySelectorAll('.chip').forEach(function(c){c.classList.remove('selected');});newChip.classList.add('selected');});var customBtn=row.querySelector('.chip.custom');if(customBtn){customBtn.parentNode.insertBefore(newChip,customBtn);}else{row.appendChild(newChip);}}}
