function lvR(){if(!s.rc)return;if(s.roomListener){db.ref('rooms/'+s.rc).off('value',s.roomListener);s.roomListener=null;}db.ref('rooms/'+s.rc+'/pl/'+s.pid).remove();db.ref('rooms/'+s.rc+'/rd/'+s.pid).remove();db.ref('rooms/'+s.rc+'/votes/'+s.pid).remove();db.ref('rooms/'+s.rc+'/pl').once('value',function(sn){var players=sn.val();var remainingPlayers=players?Object.keys(players).filter(function(id){return !players[id]?.left;}):[];if(remainingPlayers.length===0){db.ref('gi').orderByChild('roomCode').equalTo(s.rc).once('value',function(sn2){sn2.forEach(function(child){child.ref.remove();});});db.ref('rooms/'+s.rc).remove();}else{db.ref('rooms/'+s.rc+'/hid').once('value',function(sn2){var currentHost=sn2.val();if(currentHost===s.pid){var newHost=remainingPlayers[0];db.ref('rooms/'+s.rc+'/hid').set(newHost);toast('Вы стали хостом! Настройте комнату при необходимости');}});}});document.getElementById('lobbyModal').classList.remove('show');s.rc=null;s.im=false;s.lp=[];s.isGhost=false;s.inviteFromRoom=false;s.ghostWatchPid=null;s._hostNotified=false;}
function cR(){if(!s.rc){s.rc=Math.random().toString(36).substring(2,8).toUpperCase();}var pd={n:s.pn||'Игрок',a:s.pa||'?',c:s.sc};s.im=true;s.lp=[{id:s.pid,n:pd.n,a:pd.a,c:s.sc}];document.getElementById('lobbyModal').classList.add('show');ulc({rn:s.rn,mp:s.mp,sc:s.sc,rt:s.rt,tr:s.tr,pl:{},hid:s.pid,rm:s.rm,access:s.ra,bet:s.bet});var pl={};pl[s.pid]=pd;startRoomListener();var roomData={hid:s.pid,rn:s.rn,mp:s.mp,sc:s.sc,rt:s.rt,tr:s.tr,pl:pl,st:'waiting',access:s.ra,rm:s.rm,bet:s.bet};if(s.rm=='free'){var votes={};votes[s.pid]={sc:s.sc,rt:s.rt,tr:s.tr};roomData.votes=votes;}db.ref('rooms/'+s.rc).set(roomData);cl('Комната: '+s.rc);}
function joinRoom(code,params){code=code.toUpperCase().trim();db.ref('rooms/'+code).once('value',function(sn){var r=sn.val();if(!r){alert('Комната не найдена');return;}if(r.st!=='waiting'){alert('Игра уже идёт');return;}var activePlayers=r.pl?Object.keys(r.pl).filter(function(id){return !r.pl[id]?.left;}):[];if(activePlayers.length>=(r.mp||4)){alert('Комната заполнена');return;}if(r.bet>0&&s.pd<r.bet){alert('Недостаточно монет! Нужно '+r.bet);return;}s.rc=code;s.hid=r.hid||'';s.sc=r.sc||10000;s.rt=r.rt||30;s.tr=r.tr||5;s.mp=r.mp||4;s.rm=r.rm||'hard';s.ra=r.access||'open';s.bet=r.bet||0;if(s.bet>0){s.pd-=s.bet;sS();up();}if(r.gameCases){s.gameCases=r.gameCases;s.gameRound=0;}if(s.rm=='free'&&params&&s.pid!==s.hid){db.ref('rooms/'+code+'/votes/'+s.pid).set(params);}s.im=true;s.lp=[];document.getElementById('lobbyModal').classList.add('show');startRoomListener();db.ref('rooms/'+code+'/pl/'+s.pid).set({n:s.pn,a:s.pa,c:s.sc});cl('Вход: '+code);});}
