function stF(){s.fi=true;s.ft=90;clearInterval(s.fi2);clearInterval(s.fi3);document.getElementById('gameScreen').style.display='none';document.getElementById('finalOverlay').classList.add('show');upF();upFP();s.fi3=setInterval(function(){if(!s.im)botA();upFP();checkAllPlayersSold();},3000);s.fi2=setInterval(function(){s.ft-=5;if(s.ft<0)s.ft=0;document.getElementById('finalTimer').textContent=s.ft;for(var sym in s.mk)s.mk[sym]=Math.max(0.02,s.mk[sym]*(1+(Math.random()-0.46)*14/100));upF();upFP();checkAllPlayersSold();},5000);setTimeout(function(){if(!s.im)botSellAll();checkAllPlayersSold();},85000);}
