function upF(){var b=document.getElementById('finalBody'),as=Object.entries(s.yp);b.innerHTML=as.length===0?'<table><td colspan="6">Нет активов<\/td><\/tr>':as.map(function(e){var sym=e[0],d=e[1];var pr=s.mk[sym]||d.avgPrice,val=pr*d.qty,pc=d.avgPrice?((pr-d.avgPrice)/d.avgPrice*100):0,pnl=(pr-d.avgPrice)*d.qty;var cls=+pc>=0?'up':'down',arr=+pc>=0?'+':'',p=Math.abs(pc).toFixed(1);var pnlCls=pnl>=0?'pos':'neg',pnlSign=pnl>=0?'+':'';return'<tr><td class="sym">'+sym+'<\/td><td>'+d.qty+'<\/td><td>'+fm2(pr)+'<\/td><td>'+fm2(val)+'<\/td><td class="'+cls+'">'+arr+p+'%<\/td><td class="final-pnl"><span class="'+pnlCls+'">'+pnlSign+fm2(pnl)+'<\/span><\/td><\/tr>';}).join('');var totalPnl=s.yc-s.sc;for(var sym in s.yp){totalPnl+=(s.mk[sym]-s.yp[sym].avgPrice)*s.yp[sym].qty;}var totalVal=s.yc+as.reduce(function(sum,e){return sum+(s.mk[e[0]]||e[1].avgPrice)*e[1].qty;},0);var pnlCls2=totalPnl>=0?'pos':'neg',pnlSign2=totalPnl>=0?'+':'';document.getElementById('finalTotal').innerHTML=fm2(totalVal)+' <span class="final-pnl"><span class="'+pnlCls2+'">('+pnlSign2+fm2(totalPnl)+')<\/span><\/span>';}
