function shFR(){document.getElementById('freelancerRatingModal').classList.add('show');var wk=gwk();var now=new Date(),day=now.getDay(),nm=new Date(now);nm.setDate(now.getDate()+(day===0?1:8-day));nm.setHours(0,0,0,0);var diff=nm-now,ds=Math.floor(diff/86400000),hs=Math.floor((diff%86400000)/3600000);document.getElementById('ratingTimer').textContent='До конца: '+ds+'д '+hs+'ч';db.ref('fr/'+wk).orderByChild('te').limitToLast(20).once('value',function(sn){var r=sn.val();var l=document.getElementById('ratingList');if(!r){l.innerHTML='<p>Нет</p>';return;}var so=Object.entries(r).sort(function(a,b){return(b[1].te||0)-(a[1].te||0);});l.innerHTML=so.map(function(e,i){var id=e[0],rd=e[1];return'<div class="lobby-player"><span>'+(i+1)+'.</span><span class="avatar">'+av(rd.a)+'</span><span>'+(rd.n||'Игрок')+'</span><span style="margin-left:auto;color:var(--gold);">'+(rd.te||0).toFixed(0)+'</span></div>';}).join('');});}
function shGH(){document.getElementById('historyModal').classList.add('show');var l=document.getElementById('historyList');if(s.gh.length===0){l.innerHTML='<p style="color:var(--text2);">Нет</p>';return;}l.innerHTML=s.gh.slice().reverse().map(function(g){var pnl=g.profit||0;return'<div style="background:var(--surface);padding:8px;margin:4px 0;font-size:10px"><div style="color:'+(g.result=='win'?'var(--green)':'var(--red)')+';">'+(g.result=='win'?'Победа':'Поражение')+'</div><div>'+fm2(g.cash)+' | '+g.rounds+' раундов</div><div style="color:'+(pnl>=0?'var(--green)':'var(--red)')+';">P&L: '+(pnl>=0?'+':'')+fm2(pnl)+'</div></div>';}).join('');}
